#!/usr/bin/env bash
set -euo pipefail

ROOT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"

fail() {
  echo "SECURITY CHECK FAIL: $*" >&2
  exit 1
}

require_cmd() {
  command -v "$1" >/dev/null 2>&1 || fail "$1 is required"
}

rewrite_release_evidence_checksums_for_probe() {
  local run_dir="$1"
  local manifest="${run_dir}/checksums.sha256"
  if command -v sha256sum >/dev/null 2>&1; then
    (
      cd "$run_dir"
      find . -type f ! -name 'checksums.sha256' -print \
        | LC_ALL=C sort \
        | while IFS= read -r file; do
            file="${file#./}"
            sha256sum "$file"
          done
    ) > "$manifest"
  elif command -v shasum >/dev/null 2>&1; then
    (
      cd "$run_dir"
      find . -type f ! -name 'checksums.sha256' -print \
        | LC_ALL=C sort \
        | while IFS= read -r file; do
            file="${file#./}"
            shasum -a 256 "$file"
          done
    ) > "$manifest"
  else
    fail "sha256sum or shasum is required to rewrite release evidence probe checksums"
  fi
  chmod 600 "$manifest"
}

write_llm_provider_probe_fixture() {
  local provider_file="$1"
  local raw_output_dir="$2"
  local run_id="$3"
  local artifact_list_file="$4"
  node - "$provider_file" "$raw_output_dir" "$run_id" "$artifact_list_file" <<'NODE'
const fs = require("node:fs");
const path = require("node:path");

const [providerFile, rawOutputDir, runId, artifactListFile] = process.argv.slice(2);
const template = JSON.parse(fs.readFileSync("docs/llm-safety-evals/provider-run-template.json", "utf8"));
const artifacts = [];

template.runId = `${runId}-provider`;
template.runAt = "2026-06-25T00:00:00Z";
template.provider = "security-regression-provider";
template.model = "security-regression-model";
template.promptVersion = "security-regression-prompt";
template.operator = "security-regression";
template.environment.baseUrlHost = "api.example.test";
template.environment.temperature = 0;
template.environment.toolMode = "read-only";

for (const result of template.cases) {
  result.verdict = "pass";
  for (const assertion of result.assertions) {
    assertion.passed = true;
    assertion.evidence = `validated ${result.caseId}`;
  }
  result.outputSummary = `summary for ${result.caseId}`;
  result.rawOutputArtifact = result.rawOutputArtifact.replace(
    "release-evidence/<run-id>/",
    `release-evidence/${runId}/`,
  );
  result.notes = "generated by security regression";
  const relativePath = result.rawOutputArtifact.replace(`release-evidence/${runId}/`, "");
  artifacts.push(relativePath);
  const artifactFile = path.join(rawOutputDir, ...relativePath.split("/"));
  fs.mkdirSync(path.dirname(artifactFile), { recursive: true, mode: 0o700 });
  fs.writeFileSync(artifactFile, `raw output for ${result.caseId}\n`, { mode: 0o600 });
}

fs.writeFileSync(providerFile, `${JSON.stringify(template, null, 2)}\n`, { mode: 0o600 });
fs.writeFileSync(artifactListFile, `${artifacts.join("\n")}\n`, { mode: 0o600 });
NODE
}

assert_llm_provider_validator_cli_arguments_fail_closed() {
  local tmp_dir
  local output_file
  local failure=""

  tmp_dir="$(mktemp -d "${TMPDIR:-/tmp}/sourcelens-llm-provider-cli-probe.XXXXXX")" \
    || fail "could not create LLM provider validator CLI probe temp dir"
  chmod 0700 "$tmp_dir" || failure="could not harden LLM provider validator CLI probe temp dir"
  output_file="$tmp_dir/output.txt"

  cleanup_llm_provider_cli_probe() {
    rm -rf "$tmp_dir"
  }

  if [[ -z "$failure" ]]; then
    if node scripts/validate-llm-provider-run.mjs \
      docs/llm-safety-evals/provider-run-template.json \
      docs/llm-safety-evals/prompt-injection-cases.json \
      docs/llm-safety-evals/output-quality-cases.json \
      --run-id > "$output_file" 2>&1; then
      cat "$output_file" >&2
      failure="LLM provider run validator must reject --run-id without a value"
    elif ! rg -q -- '--run-id requires a non-empty release evidence run id' "$output_file"; then
      cat "$output_file" >&2
      failure="LLM provider run validator must explain missing --run-id value"
    fi
  fi
  if [[ -z "$failure" ]]; then
    if node scripts/validate-llm-provider-run.mjs \
      docs/llm-safety-evals/provider-run-template.json \
      docs/llm-safety-evals/prompt-injection-cases.json \
      docs/llm-safety-evals/output-quality-cases.json \
      --run-idd probe > "$output_file" 2>&1; then
      cat "$output_file" >&2
      failure="LLM provider run validator must reject unknown options"
    elif ! rg -q -- 'unknown option: --run-idd' "$output_file"; then
      cat "$output_file" >&2
      failure="LLM provider run validator must explain unknown options"
    fi
  fi
  if [[ -z "$failure" ]]; then
    if node scripts/validate-llm-provider-run.mjs \
      docs/llm-safety-evals/provider-run-template.json \
      docs/llm-safety-evals/prompt-injection-cases.json \
      docs/llm-safety-evals/output-quality-cases.json \
      extra-positional > "$output_file" 2>&1; then
      cat "$output_file" >&2
      failure="LLM provider run validator must reject extra positional arguments"
    elif ! rg -q -- 'usage: validate-llm-provider-run.mjs' "$output_file"; then
      cat "$output_file" >&2
      failure="LLM provider run validator must explain positional argument usage"
    fi
  fi

  cleanup_llm_provider_cli_probe
  [[ -z "$failure" ]] || fail "$failure"
}

assert_no_match() {
  local description="$1"
  local pattern="$2"
  shift 2
  local output
  if output="$(rg -n --hidden --glob '!backend-spring/target/**' --glob '!web-console/dist/**' -- "$pattern" "$@" 2>/dev/null)"; then
    echo "$output" >&2
    fail "$description"
  fi
}

assert_match() {
  local description="$1"
  local pattern="$2"
  shift 2
  rg -n --hidden --glob '!backend-spring/target/**' --glob '!web-console/dist/**' -- "$pattern" "$@" >/dev/null \
    || fail "$description"
}

assert_match_count() {
  local description="$1"
  local expected="$2"
  local pattern="$3"
  shift 3
  local count
  count="$(rg -n --hidden --glob '!backend-spring/target/**' --glob '!web-console/dist/**' -- "$pattern" "$@" 2>/dev/null \
    | wc -l | tr -d '[:space:]')"
  [[ "$count" == "$expected" ]] || fail "$description (expected $expected, got $count)"
}

assert_line_order() {
  local description="$1"
  local first_pattern="$2"
  local second_pattern="$3"
  local file="$4"
  awk -v first="$first_pattern" -v second="$second_pattern" '
    $0 ~ first && first_line == 0 {
      first_line = NR
    }
    $0 ~ second && second_line == 0 {
      second_line = NR
    }
    END {
      exit(first_line > 0 && second_line > 0 && first_line < second_line ? 0 : 1)
    }
  ' "$file" || fail "$description"
}

assert_executable() {
  local path="$1"
  [[ -x "$path" ]] || fail "$path must be executable because Makefile/CI run it directly"
}

assert_generated_artifacts_inventory_group() {
  local tmp_dir
  local output_file
  local expected_path
  local probe_root
  local probe_suffix
  local probe_dir
  local probe_dirs
  local created_probe_dirs=()
  local probe_paths
  local failure=""

  tmp_dir="$(mktemp -d "${TMPDIR:-/tmp}/sourcelens-generated-artifact-inventory.XXXXXX")" \
    || fail "could not create generated artifact inventory temp dir"
  output_file="$tmp_dir/inventory.txt"
  probe_suffix="${tmp_dir##*/}"
  probe_root=".sourcelens-generated-artifact-probe-${probe_suffix}"
  probe_paths=(
    "$probe_root/.DS_Store"
    "backend-spring/target 2/.sourcelens-generated-artifact-probe-${probe_suffix}.txt"
    "analyzer-rust/target/.sourcelens-generated-artifact-probe-${probe_suffix}.txt"
    "bin/.sourcelens-generated-artifact-probe-${probe_suffix}.txt"
    "web-console/.vite/.sourcelens-generated-artifact-probe-${probe_suffix}.txt"
    "web-console/node_modules/.vite/.sourcelens-generated-artifact-probe-${probe_suffix}.txt"
  )
  probe_dirs=(
    "$probe_root"
    "backend-spring/target 2"
    "analyzer-rust/target"
    "bin"
    "web-console/.vite"
    "web-console/node_modules"
    "web-console/node_modules/.vite"
  )

  cleanup_generated_artifact_probe() {
    local index
    local probe_path
    for probe_path in "${probe_paths[@]}"; do
      rm -f "$probe_path"
    done
    for (( index=${#created_probe_dirs[@]} - 1; index >= 0; index-- )); do
      rmdir "${created_probe_dirs[$index]}" 2>/dev/null || true
    done
  }

  cleanup_generated_artifact_inventory() {
    cleanup_generated_artifact_probe
    rm -rf "$tmp_dir"
  }

  cleanup_generated_artifact_probe
  for probe_dir in "${probe_dirs[@]}"; do
    if [[ ! -d "$probe_dir" ]]; then
      created_probe_dirs+=("$probe_dir")
    fi
  done
  mkdir -p "${probe_dirs[@]}"
  for expected_path in "${probe_paths[@]}"; do
    if [[ -e "$expected_path" ]]; then
      failure="generated artifact probe path already exists: $expected_path"
      break
    fi
    printf 'probe\n' > "$expected_path"
  done

  if [[ -z "$failure" ]]; then
    cp .git/index "$tmp_dir/index" || failure="could not copy git index for generated artifact inventory check"
  fi
  if [[ -z "$failure" ]]; then
    GIT_INDEX_FILE="$tmp_dir/index" git add -f "${probe_paths[@]}" \
      || failure="could not stage generated artifact probes in temporary git index"
  fi
  if [[ -z "$failure" ]]; then
    GIT_INDEX_FILE="$tmp_dir/index" ./scripts/worktree-inventory.sh repository-hygiene-generated-artifacts > "$output_file" \
      || failure="worktree inventory repository hygiene group must run for generated artifact probes"
  fi
  if [[ -z "$failure" ]]; then
    for expected_path in "${probe_paths[@]}"; do
      if ! rg -F -q -- "$expected_path" "$output_file"; then
        cat "$output_file" >&2
        failure="worktree inventory must put generated artifact probe in repository hygiene group: $expected_path"
        break
      fi
    done
  fi

  cleanup_generated_artifact_inventory
  [[ -z "$failure" ]] || fail "$failure"
}

assert_dependency_rejects_docker_action_workflow() {
  local tmp_dir
  local output_file
  local probe_suffix
  local probe
  local failure=""

  tmp_dir="$(mktemp -d "${TMPDIR:-/tmp}/sourcelens-docker-action-probe.XXXXXX")" \
    || fail "could not create Docker action probe temp dir"
  output_file="$tmp_dir/dependency-regression.txt"
  probe_suffix="${tmp_dir##*/}"
  probe=".github/workflows/sourcelens-docker-action-probe-${probe_suffix}.yml"

  cleanup_docker_action_probe() {
    rm -f "$probe"
    rm -rf "$tmp_dir"
  }

  if [[ -e "$probe" ]]; then
    cleanup_docker_action_probe
    fail "Docker action probe path already exists: $probe"
  fi

  cat > "$probe" <<'YAML' || failure="could not write Docker action workflow probe"
name: Docker Action Probe
on: push
jobs:
  probe:
    runs-on: ubuntu-latest
    steps:
      - uses: docker://alpine:3.20
YAML

  if [[ -z "$failure" ]]; then
    if ./scripts/dependency-regression-check.sh > "$output_file" 2>&1; then
      cat "$output_file" >&2
      failure="dependency regression must reject docker:// workflow actions"
    elif ! rg -q 'uses a Docker image action' "$output_file"; then
      cat "$output_file" >&2
      failure="dependency regression must explain docker:// workflow action rejection"
    fi
  fi

  cleanup_docker_action_probe
  [[ -z "$failure" ]] || fail "$failure"
}

assert_smoke_rejects_weak_env_before_http() {
  local tmp_dir
  local env_file
  local fake_bin
  local fake_curl
  local marker
  local output_file
  local failure=""

  tmp_dir="$(mktemp -d "${TMPDIR:-/tmp}/sourcelens-smoke-env-probe.XXXXXX")" \
    || fail "could not create smoke env probe temp dir"
  env_file="$tmp_dir/prod.env"
  fake_bin="$tmp_dir/bin"
  fake_curl="$fake_bin/curl"
  marker="$tmp_dir/curl-called.txt"
  output_file="$tmp_dir/smoke-output.txt"

  cleanup_smoke_env_probe() {
    rm -rf "$tmp_dir"
  }

  mkdir -p "$fake_bin" || failure="could not create smoke env probe bin dir"
  if [[ -z "$failure" ]]; then
    cat > "$env_file" <<'ENV' || failure="could not write smoke env probe file"
SOURCELENS_BASE_URL=http://example.test
SOURCELENS_SMOKE_TOKEN=smoke-probe-token
SOURCELENS_SMOKE_CONNECT_TIMEOUT=1
SOURCELENS_SMOKE_MAX_TIME=1
ENV
  fi
  if [[ -z "$failure" ]]; then
    chmod 0644 "$env_file" || failure="could not weaken smoke env probe permissions"
  fi
  if [[ -z "$failure" ]]; then
    cat > "$fake_curl" <<'SH' || failure="could not write fake curl probe"
#!/usr/bin/env bash
printf 'curl-called\n' >> "$SOURCELENS_FAKE_CURL_MARKER"
printf '{"status":"UP","names":[]}\n'
SH
  fi
  if [[ -z "$failure" ]]; then
    chmod 0755 "$fake_curl" || failure="could not make fake curl executable"
  fi

  if [[ -z "$failure" ]]; then
    if env -i \
      PATH="$fake_bin:/usr/bin:/bin:/usr/sbin:/sbin" \
      SOURCELENS_SMOKE_ENV_FILE="$env_file" \
      SOURCELENS_FAKE_CURL_MARKER="$marker" \
      ./scripts/smoke-test.sh > "$output_file" 2>&1; then
      cat "$output_file" >&2
      failure="smoke test must reject group/world-readable env files"
    elif ! rg -q 'permissions must not grant group/world access' "$output_file"; then
      cat "$output_file" >&2
      failure="smoke test must explain weak env file permission rejection"
    elif [[ -e "$marker" ]]; then
      cat "$output_file" >&2
      failure="smoke test must reject weak env files before any HTTP call"
    fi
  fi

  cleanup_smoke_env_probe
  [[ -z "$failure" ]] || fail "$failure"
}

assert_release_evidence_required_smoke_failure_is_verifiable() {
  local tmp_dir
  local evidence_root
  local probe_suffix
  local run_id
  local run_dir
  local output_file
  local verify_output_file
  local failure=""

  tmp_dir="$(mktemp -d "${TMPDIR:-/tmp}/sourcelens-release-smoke-probe.XXXXXX")" \
    || fail "could not create release evidence smoke probe temp dir"
  chmod 0700 "$tmp_dir" || failure="could not harden release evidence smoke probe temp dir"
  evidence_root="$tmp_dir/evidence"
  probe_suffix="${tmp_dir##*.}"
  run_id="smoke-required-${probe_suffix}"
  run_dir="$evidence_root/$run_id"
  output_file="$tmp_dir/release-evidence-output.txt"
  verify_output_file="$tmp_dir/verify-release-evidence-output.txt"

  cleanup_release_smoke_probe() {
    rm -rf "$tmp_dir"
  }

  if [[ -z "$failure" ]]; then
    if env -i \
      PATH="${PATH:-/usr/bin:/bin:/usr/sbin:/sbin}" \
      HOME="${HOME:-$tmp_dir}" \
      SOURCELENS_RELEASE_EVIDENCE_DIR="$evidence_root" \
      SOURCELENS_RELEASE_EVIDENCE_RUN_ID="$run_id" \
      SOURCELENS_RELEASE_EVIDENCE_ENV_FILE="deploy/.env.example" \
      SOURCELENS_RELEASE_EVIDENCE_INCLUDE_VERIFY=false \
      SOURCELENS_RELEASE_EVIDENCE_INCLUDE_PREFLIGHT=false \
      SOURCELENS_RELEASE_EVIDENCE_INCLUDE_SMOKE=true \
      SOURCELENS_RELEASE_EVIDENCE_INCLUDE_PHASE12=false \
      SOURCELENS_RELEASE_EVIDENCE_INCLUDE_SANDBOX_DRILL=false \
      SOURCELENS_RELEASE_EVIDENCE_INCLUDE_GITHUB_APP_DRILL=false \
      SOURCELENS_RELEASE_EVIDENCE_INCLUDE_GITHUB_WEBHOOK_DRILL=false \
      SOURCELENS_RELEASE_EVIDENCE_INCLUDE_LLM_PROVIDER_RUN=false \
      ./scripts/release-evidence.sh > "$output_file" 2>&1; then
      cat "$output_file" >&2
      failure="release evidence must fail when smoke is required without SOURCELENS_BASE_URL"
    fi
  fi
  if [[ -z "$failure" && ! -d "$run_dir" ]]; then
    cat "$output_file" >&2
    failure="release evidence must keep a verifiable package for required smoke failure"
  fi
  if [[ -z "$failure" ]] \
    && ! rg -q $'^FAIL\tsmoke\t-\tsmoke\\.log\tSOURCELENS_BASE_URL is required when SOURCELENS_RELEASE_EVIDENCE_INCLUDE_SMOKE=true$' "$run_dir/status.tsv"; then
    cat "$run_dir/status.tsv" >&2
    failure="release evidence status table must record required smoke failure"
  fi
  if [[ -z "$failure" ]] \
    && ! rg -q 'required_failures: `1`' "$run_dir/summary.md"; then
    cat "$run_dir/summary.md" >&2
    failure="release evidence summary must count required smoke failure"
  fi
  if [[ -z "$failure" ]] \
    && ! rg -q 'SOURCELENS_BASE_URL is required when SOURCELENS_RELEASE_EVIDENCE_INCLUDE_SMOKE=true' "$run_dir/smoke.log"; then
    cat "$run_dir/smoke.log" >&2
    failure="release evidence smoke log must explain missing SOURCELENS_BASE_URL"
  fi
  if [[ -z "$failure" ]]; then
    if ! ./scripts/verify-release-evidence.sh "$run_dir" > "$verify_output_file" 2>&1; then
      cat "$verify_output_file" >&2
      failure="required smoke failure release evidence package must pass verifier"
    fi
  fi

  cleanup_release_smoke_probe
  [[ -z "$failure" ]] || fail "$failure"
}

assert_release_evidence_required_phase12_failure_is_verifiable() {
  local tmp_dir
  local fake_bin
  local fake_mysql
  local marker
  local env_file
  local evidence_root
  local probe_suffix
  local run_id
  local run_dir
  local output_file
  local verify_output_file
  local failure=""

  tmp_dir="$(mktemp -d "${TMPDIR:-/tmp}/sourcelens-release-phase12-probe.XXXXXX")" \
    || fail "could not create release evidence phase12 probe temp dir"
  chmod 0700 "$tmp_dir" || failure="could not harden release evidence phase12 probe temp dir"
  fake_bin="$tmp_dir/bin"
  fake_mysql="$fake_bin/mysql"
  marker="$tmp_dir/mysql-called"
  env_file="$tmp_dir/prod.env"
  evidence_root="$tmp_dir/evidence"
  probe_suffix="${tmp_dir##*.}"
  run_id="phase12-required-${probe_suffix}"
  run_dir="$evidence_root/$run_id"
  output_file="$tmp_dir/release-evidence-output.txt"
  verify_output_file="$tmp_dir/verify-release-evidence-output.txt"

  cleanup_release_phase12_probe() {
    rm -rf "$tmp_dir"
  }

  if [[ -z "$failure" ]]; then
    mkdir -p "$fake_bin" || failure="could not create fake mysql bin dir"
  fi
  if [[ -z "$failure" ]]; then
    {
      printf '#!/usr/bin/env bash\n'
      printf 'printf invoked > "$SOURCELENS_FAKE_MYSQL_MARKER"\n'
      printf 'exit 42\n'
    } > "$fake_mysql" || failure="could not create fake mysql"
  fi
  if [[ -z "$failure" ]]; then
    chmod 700 "$fake_mysql" || failure="could not harden fake mysql"
  fi
  if [[ -z "$failure" ]]; then
    {
      printf 'SOURCELENS_PHASE12_MYSQL_EXECUTOR=host\n'
      printf 'SOURCELENS_PHASE12_SYMBOL_RELATION_THRESHOLD=500000\n'
      printf 'SOURCELENS_PHASE12_CALL_CHAIN_MS_THRESHOLD=2000\n'
    } > "$env_file" || failure="could not create phase12 probe env file"
  fi
  if [[ -z "$failure" ]]; then
    chmod 600 "$env_file" || failure="could not harden phase12 probe env file"
  fi

  if [[ -z "$failure" ]]; then
    if env -i \
      PATH="$fake_bin:${PATH:-/usr/bin:/bin:/usr/sbin:/sbin}" \
      HOME="${HOME:-$tmp_dir}" \
      SOURCELENS_FAKE_MYSQL_MARKER="$marker" \
      SOURCELENS_RELEASE_EVIDENCE_DIR="$evidence_root" \
      SOURCELENS_RELEASE_EVIDENCE_RUN_ID="$run_id" \
      SOURCELENS_RELEASE_EVIDENCE_ENV_FILE="$env_file" \
      SOURCELENS_RELEASE_EVIDENCE_INCLUDE_VERIFY=false \
      SOURCELENS_RELEASE_EVIDENCE_INCLUDE_PREFLIGHT=false \
      SOURCELENS_RELEASE_EVIDENCE_INCLUDE_SMOKE=false \
      SOURCELENS_RELEASE_EVIDENCE_INCLUDE_PHASE12=true \
      SOURCELENS_RELEASE_EVIDENCE_INCLUDE_SANDBOX_DRILL=false \
      SOURCELENS_RELEASE_EVIDENCE_INCLUDE_GITHUB_APP_DRILL=false \
      SOURCELENS_RELEASE_EVIDENCE_INCLUDE_GITHUB_WEBHOOK_DRILL=false \
      SOURCELENS_RELEASE_EVIDENCE_INCLUDE_LLM_PROVIDER_RUN=false \
      ./scripts/release-evidence.sh > "$output_file" 2>&1; then
      cat "$output_file" >&2
      failure="release evidence must fail when phase12 baseline is required without database credentials"
    fi
  fi
  if [[ -z "$failure" && ! -d "$run_dir" ]]; then
    cat "$output_file" >&2
    failure="release evidence must keep a verifiable package for required phase12 baseline failure"
  fi
  if [[ -z "$failure" ]] \
    && ! rg -q $'^FAIL\tphase12-baseline\t[1-9][0-9]*\tphase12-baseline\\.log\trequired step failed$' "$run_dir/status.tsv"; then
    cat "$run_dir/status.tsv" >&2
    failure="release evidence status table must record required phase12 baseline failure"
  fi
  if [[ -z "$failure" ]] \
    && ! rg -q 'required_failures: `1`' "$run_dir/summary.md"; then
    cat "$run_dir/summary.md" >&2
    failure="release evidence summary must count required phase12 baseline failure"
  fi
  if [[ -z "$failure" ]] \
    && ! rg -q 'DB_USERNAME or MYSQL_USER is required' "$run_dir/phase12-baseline.log"; then
    cat "$run_dir/phase12-baseline.log" >&2
    failure="release evidence phase12 baseline log must explain missing database credentials"
  fi
  if [[ -z "$failure" && -e "$marker" ]]; then
    cat "$run_dir/phase12-baseline.log" >&2
    failure="required phase12 baseline failure must happen before any MySQL query"
  fi
  if [[ -z "$failure" ]]; then
    if ! ./scripts/verify-release-evidence.sh "$run_dir" > "$verify_output_file" 2>&1; then
      cat "$verify_output_file" >&2
      failure="required phase12 baseline failure release evidence package must pass verifier"
    fi
  fi

  cleanup_release_phase12_probe
  [[ -z "$failure" ]] || fail "$failure"
}

assert_release_evidence_missing_manual_evidence_failure_is_verifiable() {
