      SOURCELENS_RELEASE_EVIDENCE_INCLUDE_GITHUB_APP_DRILL=false \
      SOURCELENS_RELEASE_EVIDENCE_INCLUDE_GITHUB_WEBHOOK_DRILL=false \
      SOURCELENS_RELEASE_EVIDENCE_INCLUDE_LLM_PROVIDER_RUN=false \
      SOURCELENS_BACKUP_RESTORE_DRILL_EVIDENCE_FILE="$restore_evidence_file" \
      SOURCELENS_ROLLBACK_PLAN_FILE="$rollback_plan_file" \
      ./scripts/release-evidence.sh > "$output_file" 2>&1; then
      cat "$output_file" >&2
      failure="release evidence must fail when configured manual evidence files are missing"
    fi
  fi
  if [[ -z "$failure" && ! -d "$run_dir" ]]; then
    cat "$output_file" >&2
    failure="release evidence must keep a verifiable package for missing manual evidence failure"
  fi
  if [[ -z "$failure" ]] \
    && ! rg -q $'^FAIL\tbackup-restore-drill-evidence\t-\tbackup-restore-drill-evidence\\.log\tSOURCELENS_BACKUP_RESTORE_DRILL_EVIDENCE_FILE does not point to a regular file:' "$run_dir/status.tsv"; then
    cat "$run_dir/status.tsv" >&2
    failure="release evidence status table must record missing backup restore drill evidence failure"
  fi
  if [[ -z "$failure" ]] \
    && ! rg -q $'^FAIL\trollback-plan\t-\trollback-plan\\.log\tSOURCELENS_ROLLBACK_PLAN_FILE does not point to a regular file:' "$run_dir/status.tsv"; then
    cat "$run_dir/status.tsv" >&2
    failure="release evidence status table must record missing rollback plan failure"
  fi
  if [[ -z "$failure" ]] \
    && ! rg -q 'required_failures: `2`' "$run_dir/summary.md"; then
    cat "$run_dir/summary.md" >&2
    failure="release evidence summary must count both missing manual evidence failures"
  fi
  if [[ -z "$failure" ]] \
    && ! rg -q 'SOURCELENS_BACKUP_RESTORE_DRILL_EVIDENCE_FILE does not point to a regular file' "$run_dir/backup-restore-drill-evidence.log"; then
    cat "$run_dir/backup-restore-drill-evidence.log" >&2
    failure="release evidence backup restore drill evidence log must explain missing file"
  fi
  if [[ -z "$failure" ]] \
    && ! rg -q 'SOURCELENS_ROLLBACK_PLAN_FILE does not point to a regular file' "$run_dir/rollback-plan.log"; then
    cat "$run_dir/rollback-plan.log" >&2
    failure="release evidence rollback plan log must explain missing file"
  fi
  if [[ -z "$failure" && -e "$run_dir/backup-restore-drill-evidence.txt" ]]; then
    cat "$run_dir/status.tsv" >&2
    failure="missing backup restore drill evidence failure must not archive a manual evidence txt file"
  fi
  if [[ -z "$failure" && -e "$run_dir/rollback-plan.txt" ]]; then
    cat "$run_dir/status.tsv" >&2
    failure="missing rollback plan failure must not archive a rollback plan txt file"
  fi
  if [[ -z "$failure" ]]; then
    if ! ./scripts/verify-release-evidence.sh "$run_dir" > "$verify_output_file" 2>&1; then
      cat "$verify_output_file" >&2
      failure="missing manual evidence failure release evidence package must pass verifier"
    fi
  fi

  cleanup_release_manual_evidence_probe
  [[ -z "$failure" ]] || fail "$failure"
}

assert_release_evidence_checksum_tamper_is_rejected() {
  local tmp_dir
  local evidence_root
  local probe_suffix
  local run_id
  local run_dir
  local output_file
  local verify_output_file
  local tamper_output_file
  local failure=""

  tmp_dir="$(mktemp -d "${TMPDIR:-/tmp}/sourcelens-release-tamper-probe.XXXXXX")" \
    || fail "could not create release evidence tamper probe temp dir"
  chmod 0700 "$tmp_dir" || failure="could not harden release evidence tamper probe temp dir"
  evidence_root="$tmp_dir/evidence"
  probe_suffix="${tmp_dir##*.}"
  run_id="tamper-check-${probe_suffix}"
