  if [[ -z "$failure" ]]; then
    cp "$original_status_file" "$run_dir/status.tsv" \
      && cp "$original_summary_file" "$run_dir/summary.md" \
      && chmod 600 "$run_dir/status.tsv" "$run_dir/summary.md" \
      || failure="could not restore original files before worktree status probe"
  fi
  if [[ -z "$failure" ]]; then
    rewrite_release_evidence_checksums_for_probe "$run_dir"
  fi
  if [[ -z "$failure" ]]; then
    if ! awk -F '\t' '
      BEGIN {
        OFS = "\t"
      }
      NR == 1 {
        print
        next
      }
      $2 == "worktree-inventory" && !changed {
        $1 = "SKIP"
        $3 = "-"
        $5 = "worktree inventory skipped"
        changed = 1
      }
      {
        print
      }
      END {
        exit(changed ? 0 : 1)
      }
    ' "$run_dir/status.tsv" > "$tampered_status_file"; then
      failure="could not forge worktree inventory status as SKIP"
    fi
  fi
  if [[ -z "$failure" ]]; then
    if ! awk '
      /^- OK `worktree-inventory`: / && !changed {
        print "- SKIP `worktree-inventory`: Worktree inventory snapshot (worktree inventory skipped)"
        changed = 1
        next
      }
      /^- skipped: `/ {
        line = $0
        sub(/^- skipped: `/, "", line)
        sub(/`[[:space:]]*$/, "", line)
        print "- skipped: `" line + 1 "`"
        next
      }
      {
        print
      }
      END {
        exit(changed ? 0 : 1)
      }
    ' "$run_dir/summary.md" > "$tampered_summary_file"; then
      failure="could not forge worktree inventory summary as SKIP"
    fi
  fi
  if [[ -z "$failure" ]]; then
    mv "$tampered_status_file" "$run_dir/status.tsv" \
      && mv "$tampered_summary_file" "$run_dir/summary.md" \
      && chmod 600 "$run_dir/status.tsv" "$run_dir/summary.md" \
      || failure="could not replace worktree inventory tampered files"
  fi
  if [[ -z "$failure" ]]; then
    rewrite_release_evidence_checksums_for_probe "$run_dir"
  fi
  if [[ -z "$failure" ]]; then
    if ./scripts/verify-release-evidence.sh "$run_dir" > "$worktree_skip_output_file" 2>&1; then
      cat "$worktree_skip_output_file" >&2
      failure="release evidence verifier must reject worktree inventory status forged as SKIP after checksums are regenerated"
    elif ! rg -q 'release evidence worktree-inventory status must not be SKIP' "$worktree_skip_output_file"; then
      cat "$worktree_skip_output_file" >&2
      failure="release evidence verifier must explain worktree inventory status tampering"
    fi
  fi

  cleanup_release_core_status_probe
  [[ -z "$failure" ]] || fail "$failure"
}

