smoke_base_url_output="$(mktemp "${TMPDIR:-/tmp}/sourcelens-base-url-shape.XXXXXX")" \
  || fail "could not create smoke base URL output temp file"
if SOURCELENS_SMOKE_ENV_FILE=/tmp/sourcelens-smoke-missing.env \
  SOURCELENS_BASE_URL='https://token@example.test' \
  ./scripts/smoke-test.sh > "$smoke_base_url_output" 2>&1; then
  cat "$smoke_base_url_output" >&2
  rm -f "$smoke_base_url_output"
  fail "smoke test must reject base URLs with user-info"
elif ! rg -q 'SOURCELENS_BASE_URL must not contain user-info, query or fragment' "$smoke_base_url_output"; then
  cat "$smoke_base_url_output" >&2
  rm -f "$smoke_base_url_output"
  fail "smoke test must explain unsafe base URL shape"
fi
rm -f "$smoke_base_url_output"

