preflight_require_github_output="$(mktemp "${TMPDIR:-/tmp}/sourcelens-prod-preflight-require-github-mode.XXXXXX")" \
  || fail "could not create production preflight GitHub App mode output temp file"
if SOURCELENS_PREFLIGHT_REQUIRE_GITHUB_APP=maybe ./scripts/production-preflight.sh > "$preflight_require_github_output" 2>&1; then
  cat "$preflight_require_github_output" >&2
  rm -f "$preflight_require_github_output"
  fail "production preflight must reject invalid GitHub App readiness mode values"
elif ! rg -q 'SOURCELENS_PREFLIGHT_REQUIRE_GITHUB_APP must be true or false' "$preflight_require_github_output"; then
  cat "$preflight_require_github_output" >&2
  rm -f "$preflight_require_github_output"
  fail "production preflight must explain invalid GitHub App readiness mode values"
fi
rm -f "$preflight_require_github_output"

preflight_agent_pr_output="$(mktemp "${TMPDIR:-/tmp}/sourcelens-prod-preflight-agent-pr-mode.XXXXXX")" \
  || fail "could not create production preflight Agent PR mode output temp file"
if SOURCELENS_AGENT_CREATE_PR_ENABLED=ture ./scripts/production-preflight.sh > "$preflight_agent_pr_output" 2>&1; then
  cat "$preflight_agent_pr_output" >&2
  rm -f "$preflight_agent_pr_output"
  fail "production preflight must reject invalid Agent controlled PR mode values"
elif ! rg -q 'SOURCELENS_AGENT_CREATE_PR_ENABLED must be true or false' "$preflight_agent_pr_output"; then
  cat "$preflight_agent_pr_output" >&2
  rm -f "$preflight_agent_pr_output"
  fail "production preflight must explain invalid Agent controlled PR mode values"
fi
rm -f "$preflight_agent_pr_output"

preflight_autorepair_pr_output="$(mktemp "${TMPDIR:-/tmp}/sourcelens-prod-preflight-autorepair-pr-mode.XXXXXX")" \
  || fail "could not create production preflight AutoRepair PR mode output temp file"
if SOURCELENS_AUTOREPAIR_SUBMIT_PR_ENABLED=ture ./scripts/production-preflight.sh > "$preflight_autorepair_pr_output" 2>&1; then
  cat "$preflight_autorepair_pr_output" >&2
  rm -f "$preflight_autorepair_pr_output"
  fail "production preflight must reject invalid AutoRepair controlled PR mode values"
elif ! rg -q 'SOURCELENS_AUTOREPAIR_SUBMIT_PR_ENABLED must be true or false' "$preflight_autorepair_pr_output"; then
  cat "$preflight_autorepair_pr_output" >&2
  rm -f "$preflight_autorepair_pr_output"
  fail "production preflight must explain invalid AutoRepair controlled PR mode values"
fi
rm -f "$preflight_autorepair_pr_output"

rollback_agent_pr_output="$(mktemp "${TMPDIR:-/tmp}/sourcelens-rollback-preflight-stop-switch-mode.XXXXXX")" \
  || fail "could not create rollback preflight Agent stop-switch output temp file"
if SOURCELENS_ROLLBACK_PREFLIGHT_ENV_FILE=/tmp/sourcelens-rollback-preflight-missing.env \
  SOURCELENS_AGENT_CREATE_PR_ENABLED=ture \
  ./scripts/rollback-preflight.sh > "$rollback_agent_pr_output" 2>&1; then
  cat "$rollback_agent_pr_output" >&2
  rm -f "$rollback_agent_pr_output"
  fail "rollback preflight must reject invalid Agent stop-switch values"
elif ! rg -q 'SOURCELENS_AGENT_CREATE_PR_ENABLED must be false or unset during rollback' "$rollback_agent_pr_output"; then
  cat "$rollback_agent_pr_output" >&2
  rm -f "$rollback_agent_pr_output"
  fail "rollback preflight must explain invalid Agent stop-switch values"
fi
rm -f "$rollback_agent_pr_output"

rollback_autorepair_pr_output="$(mktemp "${TMPDIR:-/tmp}/sourcelens-rollback-preflight-stop-switch-mode.XXXXXX")" \
  || fail "could not create rollback preflight AutoRepair stop-switch output temp file"
if SOURCELENS_ROLLBACK_PREFLIGHT_ENV_FILE=/tmp/sourcelens-rollback-preflight-missing.env \
  SOURCELENS_AUTOREPAIR_SUBMIT_PR_ENABLED=true \
  ./scripts/rollback-preflight.sh > "$rollback_autorepair_pr_output" 2>&1; then
  cat "$rollback_autorepair_pr_output" >&2
  rm -f "$rollback_autorepair_pr_output"
  fail "rollback preflight must reject enabled AutoRepair stop-switch values"
elif ! rg -q 'SOURCELENS_AUTOREPAIR_SUBMIT_PR_ENABLED must be false or unset during rollback' "$rollback_autorepair_pr_output"; then
  cat "$rollback_autorepair_pr_output" >&2
  rm -f "$rollback_autorepair_pr_output"
  fail "rollback preflight must explain enabled AutoRepair stop-switch values"
fi
rm -f "$rollback_autorepair_pr_output"

rollback_base_url_output="$(mktemp "${TMPDIR:-/tmp}/sourcelens-base-url-shape.XXXXXX")" \
  || fail "could not create rollback base URL output temp file"
if SOURCELENS_ROLLBACK_PREFLIGHT_ENV_FILE=/tmp/sourcelens-rollback-preflight-missing.env \
  SOURCELENS_BASE_URL='https://token@example.test' \
  ./scripts/rollback-preflight.sh > "$rollback_base_url_output" 2>&1; then
  cat "$rollback_base_url_output" >&2
  rm -f "$rollback_base_url_output"
  fail "rollback preflight must reject base URLs with user-info"
elif ! rg -q 'SOURCELENS_BASE_URL must not contain user-info, query or fragment' "$rollback_base_url_output"; then
  cat "$rollback_base_url_output" >&2
  rm -f "$rollback_base_url_output"
  fail "rollback preflight must explain unsafe base URL shape"
fi
rm -f "$rollback_base_url_output"

