  ./scripts/github-webhook-drill.sh > "$github_webhook_base_url_output" 2>&1; then
  cat "$github_webhook_base_url_output" >&2
  rm -f "$github_webhook_base_url_output"
  fail "GitHub webhook drill must reject base URLs without a host"
elif ! rg -q 'SOURCELENS_BASE_URL must include a host' "$github_webhook_base_url_output"; then
  cat "$github_webhook_base_url_output" >&2
  rm -f "$github_webhook_base_url_output"
  fail "GitHub webhook drill must explain empty base URL hosts"
elif rg -q '^== Webhook endpoint drill ==' "$github_webhook_base_url_output"; then
  cat "$github_webhook_base_url_output" >&2
  rm -f "$github_webhook_base_url_output"
  fail "GitHub webhook drill must reject invalid base URLs before HTTP calls"
fi
